const RANGED_WEAPONS=new Set(['lightCrossbow','dart','shortbow','sling','blowgun','handCrossbow','heavyCrossbow','longbow','musket','pistol']);
function weaponSpec(item){const chosen=item.effects?.weaponType;if(chosen&&WEAPONS[chosen])return WEAPONS[chosen];const name=String(item.name||'').toLowerCase().replace(/ё/g,'е');return Object.values(WEAPONS).sort((a,b)=>b[0].length-a[0].length).find(([label])=>name.includes(label.toLowerCase().replace(/ё/g,'е').replace(/ь$/,'')))||null;}
function weaponRangeType(item){if(item.effects?.weaponType)return RANGED_WEAPONS.has(item.effects.weaponType)?'ranged':'melee';const spec=weaponSpec(item);if(!spec)return'melee';const entry=Object.entries(WEAPONS).find(([,value])=>value===spec);return entry&&RANGED_WEAPONS.has(entry[0])?'ranged':'melee';}
function weaponHands(item){const explicit=item.effects?.weaponHands;if(['one','versatile','two','shield'].includes(explicit))return explicit;const type=item.effects?.weaponType;if(TWO_HANDED_WEAPONS.has(type))return'two';if(VERSATILE_WEAPONS.has(type))return'versatile';return'one';}
function handSlot(slot){return ['meleeMain','meleeOff','rangedMain','rangedOff'].includes(slot);}
function pairedHandSlot(slot){return {meleeMain:'meleeOff',meleeOff:'meleeMain',rangedMain:'rangedOff',rangedOff:'rangedMain'}[slot];}
function itemFitsSlot(item,slot){const allowed=ITEM_TYPE_SLOTS[item.itemType];if(allowed&&!allowed.includes(slot))return false;if(allowed&&!handSlot(slot))return true;if(!handSlot(slot))return !allowed;const hands=weaponHands(item);if(item.itemType==='shield'||hands==='shield')return slot==='meleeOff';if(!weaponSpec(item)&&!['meleeWeapon','rangedWeapon'].includes(item.itemType))return false;const ranged=item.itemType==='rangedWeapon'||(item.itemType!=='meleeWeapon'&&weaponRangeType(item)==='ranged');if(ranged!==slot.startsWith('ranged'))return false;return hands!=='two'||slot.endsWith('Main');}
function recommendedSlotText(type){const slots=ITEM_TYPE_SLOTS[type]||[];return slots.length?slots.map(slot=>EQUIPMENT_SLOTS[slot][0]).join(' или '):'любой подходящий слот';}
function rangeBonuses(s,type){return type==='ranged'?{attack:s.itemBonuses.rangedAttack||0,damage:s.itemBonuses.rangedDamage||0}:{attack:s.itemBonuses.meleeAttack||0,damage:s.itemBonuses.meleeDamage||0};}
function itemWeaponAttacks(s){return (s.weaponItems||[]).map(item=>{const spec=weaponSpec(item);if(!spec)return null;const [label,die,ability]=spec,fx=item.effects||{},rangeType=weaponRangeType(item),attack=s.mods[ability]+s.prof+(Number(fx.attack)||0),abilityDamage=item.equipmentSlot?.endsWith('Off')?0:s.mods[ability],damage=abilityDamage+(Number(fx.damage)||0);return{name:item.name||label,notes:[`${label} · ${rangeType==='ranged'?'дальнобойное':'ближнее'} оружие · ${weaponHands(item)==='two'?'двуручное':weaponHands(item)==='versatile'?'универсальное':'одноручное'} · магический предмет`,item.notes].filter(Boolean).join('\n'),ability,rangeType,attack,damage:die+(damage?signed(damage):''),itemId:item.id};}).filter(Boolean);}
function attackCards(c,s){const manual=(c.attacks||[]).map((a,i)=>{const type=a.rangeType||'melee',isSpell=type==='spell',range=rangeBonuses(s,type);return{name:a.name,notes:[isSpell?'Заклинание':type==='ranged'?'Оружие дальнего боя':'Оружие ближнего боя',a.notes].filter(Boolean).join('\n'),attack:s.mods[a.ability]+(a.proficient?s.prof:0)+(a.bonus||0)+(isSpell?(s.itemBonuses.spellAttack||0):(s.itemBonuses.attack||0)+range.attack),damage:isSpell?addFormulaBonus(a.damage,a.spellAbilityDamage?s.mods[a.ability]:0):addFormulaBonus(a.damage,(a.hand==='main'?s.mods[a.ability]:0)+(s.itemBonuses.damage||0)+range.damage),edit:i};}),items=itemWeaponAttacks(s).map(a=>{const range=rangeBonuses(s,a.rangeType);return{...a,attack:a.attack+(s.itemBonuses.attack||0)+range.attack,damage:addFormulaBonus(a.damage,(s.itemBonuses.damage||0)+range.damage)};}),all=[...items,...manual];return all.map(a=>`<div class="attack-card ${a.itemId?'item-attack':''}"><div><b>${esc(a.name)}</b>${a.itemId?'<span class="item-magic">ИЗ ПРЕДМЕТА</span>':''}<small>${esc(a.notes)}</small></div><div>${btn('Атака '+signed(a.attack),'roll','outline',`data-formula="1d20${signed(a.attack)}" data-label="${esc(a.name)}: атака"`)}${btn(esc(a.damage),'roll','outline',`data-formula="${esc(a.damage)}" data-label="${esc(a.name)}: урон"`)}${a.edit===undefined?'':btn('✎','attack-edit','subtle',`data-index="${a.edit}" aria-label="Изменить атаку"`)}</div></div>`).join('')||'<p class="empty-text">Добавьте оружие или заклинание с броском атаки. Бонус мастерства и характеристика будут пересчитываться автоматически.</p>';}
