function spellLimits(c,s){const maxCircle=s.slots.at(-1)?.level||0,cantrips=c.spells.filter(x=>!x.custom&&spellOf(x.id).level===0).length,leveled=c.spells.filter(x=>!x.custom&&spellOf(x.id).level>0).length,knownMax=c.classId==='wizard'?4+2*c.level:s.prepared;return {maxCircle,cantrips,leveled,knownMax};}
function spellRestriction(p,c,s){const limits=spellLimits(c,s);if(!p.classes.includes(c.classId))return 'Нет в списке заклинаний класса';if(p.level>limits.maxCircle)return `Круг откроется позже (доступен ${limits.maxCircle||0})`;if(p.level===0&&limits.cantrips>=s.cantrips)return `Лимит заговоров: ${s.cantrips}`;if(p.level>0&&limits.leveled>=limits.knownMax)return `${c.classId==='wizard'?'Лимит в книге на этом уровне':'Лимит известных/подготовленных'}: ${limits.knownMax}`;return '';}
