function shell(){return `<aside class="sidebar"><a class="brand" href="#" data-action="party"><span class="brand-mark">✧</span><span>Книга судеб<small>ВАША ИСТОРИЯ НАЧИНАЕТСЯ ЗДЕСЬ</small></span></a><div class="nav-label">ВАШ СТОЛ</div><nav>${[['party',cloud.user?'Мои персонажи':'Моя партия'],['library','Библиотека'],['journal','Заметки партии']].map(([id,label])=>`<button data-action="nav" data-page="${id}" class="nav-item ${page===id?'active':''}"><span>${ICONS[id]||ICONS.notes}</span>${label}${id==='party'?`<em>${state.characters.length}</em>`:''}</button>`).join('')}</nav><div class="nav-label party-label">ПЕРСОНАЖИ <button data-action="new" aria-label="Добавить персонажа">+</button></div><div class="party-list">${state.characters.map(c=>`<button class="party-person ${page==='character'&&selected===c.id?'selected':''}" data-action="open" data-id="${esc(c.id)}">${avatar(c)}<span>${esc(c.name)}<small>${esc(nameOf('classes',c.classId))} · ${c.level} ур.</small></span></button>`).join('')}</div><div class="sidebar-bottom"><div class="edition"><span class="status-dot"></span>ПРАВИЛА 2024 <span>5e</span></div><button class="nav-item" data-action="rules"><span>⊙</span>О книге и правилах</button><p>Пусть кости будут<br>на вашей стороне.</p><span class="tiny-ornament">― ✧ ―</span></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb">КАМПАНИЯ <span>/</span> ${page==='character'?esc(current()?.name||'Персонаж'):page==='library'?'Библиотека':page==='journal'?'Заметки партии':'Моя партия'}</div><div class="top-actions"><span id="save-status" class="save-status"><i></i>${saveLabel()}</span>${btn(cloud.user?'Мой аккаунт':'Войти','account','subtle')}${btn('↥ <span>Импорт</span>','import','subtle')}${btn('↧ <span>Скачать копию</span>','export','subtle')}</div></header><main id="main"></main><footer>КНИГА СУДЕБ <span>Собирайте истории. Берегите свою партию.</span><button data-action="rules">Правила и источники ↗</button></footer></div>`;}
