  if(a==='section'){section=el.dataset.section;filter='';render();return;}
  if(a==='new')return editDialog(createCharacter(),true);
  if(a==='edit')return editDialog(c);
  if(a==='level')return levelDialog();
  if(a==='rules')return rulesDialog();
  if(a==='ready')return mutate(()=>c.draft=false);
  if(a==='export')return exportChars();
  if(a==='export-one')return exportChars([c]);
  if(a==='export-dataset')return download('party-dataset.json',rawDataset);
  if(a==='import'||a==='import-dataset'){$('#import-file').dataset.mode=a;$('#import-file').click();return;}
  if(a==='avatar'){$('#avatar-file').click();return;}
  if(a==='duplicate'){mutate(()=>{const copy=structuredClone(c);copy.id=crypto.randomUUID();copy.name+=' — копия';state.characters.push(copy);selected=copy.id;});toast('Копия добавлена');return;}
  if(a==='delete'){showDialog('Удалить персонажа?',`<p><b>${esc(c.name)}</b> будет удалён из вашей книги. Перед удалением можно скачать его лист.</p><p class="warning">После следующего изменения отменить удаление будет нельзя.</p><div class="dialog-actions">${btn('Скачать лист','export-one','outline')}${btn('Отмена','close','outline')}${btn('Удалить персонажа','confirm-delete','primary danger')}</div>`);return;}
  if(a==='confirm-delete'){mutate(()=>{state.characters=state.characters.filter(x=>x.id!==c.id);selected=state.characters[0]?.id;page='party';});$('#dialog').close();toast('Персонаж удалён. Можно отменить изменение.');showDialog('Персонаж удалён',`<p>Персонаж удалён из вашей книги.</p><div class="dialog-actions">${btn('↶ Восстановить персонажа','undo','primary')}${btn('Закрыть','close','outline')}</div>`);return;}
  if(a==='undo'){if(undoSnapshot){state=undoSnapshot;undoSnapshot=null;save();render();$('#dialog').close();toast('Изменение отменено');}return;}
  if(a==='print'){section='sheet';render();window.print();return;}
  if(a==='roll')return roll(el.dataset.formula,el.dataset.label,el.dataset.advantage==='true');
  if(a==='inspiration')return mutate(()=>c.inspiration=!c.inspiration);
  if(a==='damage'||a==='heal'){const amount=clamp($('#hp-amount').value,0,999);mutate(()=>{if(a==='damage'){const soak=Math.min(c.tempHp,amount);c.tempHp-=soak;c.damage=clamp(c.damage+amount-soak,0,s.hpMax);}else c.damage=Math.max(0,c.damage-amount);});return;}
