  if(a==='start-combat')return mutate(()=>{c.spent['elation-ardor']=c.level>=6?2:4;c.ardorGained=0;c.jackpotUsed=false;});
  if(a==='new-turn')return mutate(()=>{c.ardorGained=0;c.jackpotUsed=false;});
  if(a==='jackpot'){if((s.resources.find(x=>x.id==='elation-ardor')?.remaining||0)<4)return toast('Для Джекпота нужно 4 Пыла');if(c.jackpotUsed)return toast('Джекпот уже использован в этом раунде');mutate(()=>{c.spent['elation-ardor']=4;c.jackpotUsed=true;});roll(c.level>=10?'3d6':'2d6','Джекпот · спасбросок Ловкости Сл '+s.spellDC);return;}
  if(a==='slot')return mutate(()=>c.spent[el.dataset.id]=Number(el.dataset.value));
  if(a==='conditions'){showDialog('Состояния',`<div class="condition-grid">${['Ослеплён','Очарован','Оглох','Испуган','Схвачен','Недееспособен','Невидим','Парализован','Окаменел','Отравлен','Сбит с ног','Опутан','Ошеломлён','Без сознания','Истощение 1','Истощение 2','Истощение 3','Истощение 4','Истощение 5'].map(x=>`<label class="check-label"><input type="checkbox" data-condition="${x}" ${c.conditions.includes(x)?'checked':''}>${x}</label>`).join('')}</div><p class="hint">Это отметки для игры. Ситуативные помехи, преимущества и штрафы применяйте при броске.</p>`);return;}
