  if(a==='feature-remove'){mutate(()=>c.manualFeatures=c.manualFeatures.filter(x=>x.id!==el.dataset.id));$('#dialog').close();return;}
  if(a==='item-slot')return equipmentSlotDialog(el.dataset.slot);
  if(a==='item-slot-equip'){mutate(()=>{c.itemOverrides??={};const target=allCharacterItems(c,s).find(item=>item.id===el.dataset.id);unequipConflictingItems(c,s,el.dataset.id,el.dataset.slot,target);if(el.dataset.slot==='armor')c.armor='none';if(el.dataset.slot==='meleeOff')c.shield=false;c.itemOverrides[el.dataset.id]={...(c.itemOverrides[el.dataset.id]||{}),equipped:true,equipmentSlot:el.dataset.slot};});$('#dialog').close();toast(`Предмет надет: ${EQUIPMENT_SLOTS[el.dataset.slot]?.[0]||'экипировка'}`);return;}
