  if(a==='item-spell-clear'){const input=$('#item-spell-id');if(input){input.value='';renderItemSpellPicker();}return;}
  if(a==='item-save'){const value=itemFormValue(el.closest('form'));if(!value.name||!Number.isInteger(value.qty)||value.qty<0||value.qty>9999)return toast('Проверьте название и количество предмета');let autoSlot='';mutate(()=>autoSlot=saveItemValue(c,s,value));$('#dialog').close();if(autoSlot)toast(`Предмет автоматически надет: ${EQUIPMENT_SLOTS[autoSlot][0]}`);else if(!value.equipped&&(ITEM_TYPE_SLOTS[value.itemType]||[]).length)replacementDialog(value.id);else toast('Предмет и его эффекты сохранены');return;}
  if(a==='item-sale'){const item=[...s.equipment,...(c.inventory||[])].map(entry=>({...entry,...(c.itemOverrides?.[entry.id]||{})})).find(entry=>entry.id===el.dataset.id);if(!item)return;mutate(()=>{c.itemOverrides??={};c.itemOverrides[item.id]={...(c.itemOverrides[item.id]||{}),forSale:!item.forSale};});toast(item.forSale?'Отметка «На продажу» снята':'Предмет помечен «На продажу»');return;}
